const $=s=>document.querySelector(s), COLORS={gum:'#62a988',sun:'#d5b95e',reef:'#6799c1',clay:'#d77859'}, EMOJIS=['🦘','🐨','🦜','🦔','🦦','🦉'];
let page='home',setup={mode:'mix',players:3,style:'ai',name:'Roo Rider',music:false},game=null,selected=null,awaitingPass=false,awaitingColor=null,turnTimer=null;
const saved=JSON.parse(localStorage.getItem('looStats')||'{}');let stats={wins:saved.wins||0,played:saved.played||0,streak:saved.streak||0,points:saved.points||0};
function saveStats(){localStorage.setItem('looStats',JSON.stringify(stats))}
function showPage(p){page=p;document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.page===p));render()}
function render(){const m=$('#main');if(page==='home')m.innerHTML=homeHTML();if(page==='setup')m.innerHTML=setupHTML();if(page==='game')m.innerHTML=gameHTML();if(page==='tournament')m.innerHTML=tournamentHTML();if(page==='leaderboard')m.innerHTML=leaderHTML();if(page==='rules')m.innerHTML=rulesHTML();if(page==='game')bindGame();}
function homeHTML(){return `<section class="hero"><div class="hero-copy"><div class="eyebrow">A LITTLE CHAOS, DOWN UNDER</div><h1>One deck.<br><em>No mercy.</em></h1><p>Match, stack, flip the table — and be the last one holding cards. Backyard rules, proper Aussie attitude.</p><button class="primary" onclick="showPage('setup')">PLAY A ROUND&nbsp; →</button></div><div class="hero-cards"><div class="demo-card one">↻</div><div class="demo-card two">✦</div><div class="demo-card three">+4</div></div></section><div class="sectionhead"><div><h2>Pick your flavour</h2><p>Both sides of the deck. One gloriously bad idea.</p></div><button class="textlink" onclick="showPage('rules')">HOW TO PLAY ↗</button></div><section class="modegrid"><article class="modecard" onclick="setup.mode='flip';showPage('setup')"><span class="modebadge">TWO-SIDED MAYHEM</span><div class="modeicon">↻</div><h3>Storm & Scrub</h3><p>Flip the deck when the weather turns. Gentle plays become proper hard yakka.</p></article><article class="modecard" onclick="setup.mode='mercy';showPage('setup')"><span class="modebadge">STACK AT YOUR OWN RISK</span><div class="modeicon">⚡</div><h3>No Worries, No Mercy</h3><p>Stack draw cards, pass the pain along, and try not to bust out at 25.</p></article></section><div class="statsrow"><div class="statbox"><small>ROUNDS PLAYED</small><strong>${stats.played}<span> rounds</span></strong></div><div class="statbox"><small>WINS</small><strong>${stats.wins}<span> victories</span></strong></div><div class="statbox"><small>CLUB POINTS</small><strong>${stats.points}<span> pts</span></strong></div></div>`}
function setupHTML(){return `<div class="setup"><div class="eyebrow">SET UP YOUR GAME</div><h1 class="page-title">Who's in?</h1><p class="page-sub">Pick a mode, round up the crew, then let the chaos begin.</p><div class="setupgrid"><section class="setupbox"><h3>GAME MODE</h3><div class="choices"><button class="choice ${setup.mode==='mix'?'selected':''}" onclick="pick('mode','mix',this)">Backyard Mix</button><button class="choice ${setup.mode==='flip'?'selected':''}" onclick="pick('mode','flip',this)">Storm & Scrub</button><button class="choice ${setup.mode==='mercy'?'selected':''}" onclick="pick('mode','mercy',this)">No Mercy</button></div><div class="toggleline">Stack draw cards <button class="switch ${setup.stack!==false?'on':''}" onclick="setup.stack=this.classList.toggle('on');this.classList.contains('on')" aria-label="Toggle stacking"></button></div><div class="toggleline">Bust out at 25 cards <button class="switch ${setup.bust!==false?'on':''}" onclick="setup.bust=this.classList.toggle('on')" aria-label="Toggle bust rule"></button></div></section><section class="setupbox"><h3>WHO'S PLAYING?</h3><div class="choices"><button class="choice ${setup.style==='ai'?'selected':''}" onclick="pick('style','ai',this)">Vs the locals</button><button class="choice ${setup.style==='pass'?'selected':''}" onclick="pick('style','pass',this)">Pass & play</button></div><div class="choices" style="margin-top:11px"><button class="choice ${setup.players===2?'selected':''}" onclick="pick('players',2,this)">2 players</button><button class="choice ${setup.players===3?'selected':''}" onclick="pick('players',3,this)">3 players</button><button class="choice ${setup.players===4?'selected':''}" onclick="pick('players',4,this)">4 players</button></div><input class="nameinput" maxlength="14" value="${setup.name}" placeholder="Your nickname" oninput="setup.name=this.value"></section></div><div class="setupbox" style="margin-top:14px"><h3>THE CLUBHOUSE</h3><p style="color:var(--muted);font-size:11px;margin:0">Local games and couch pass-and-play are ready. Online rooms, tournaments and worldwide rankings are coming soon — your stats stay on this device.</p></div><div class="setup-actions"><button class="primary" onclick="startGame()">DEAL THE CARDS&nbsp; →</button><button class="secondary" onclick="showPage('home')">Back</button></div></div>`}
function pick(key,val,el){setup[key]=val;const group=el.parentElement;group.querySelectorAll('.choice').forEach(b=>b.classList.remove('selected'));el.classList.add('selected')}
function makeDeck(){let deck=[],sideCount=setup.mode==='flip'?2:1,colors=Object.keys(COLORS);for(let side=0;side<sideCount;side++){for(const color of colors){for(let n=0;n<=9;n++){deck.push({color,value:String(n),side});if(n>0)deck.push({color,value:String(n),side})}for(const value of ['Skip','Reverse','+2']){deck.push({color,value,side},{color,value,side})}}for(let i=0;i<4;i++)deck.push({color:'wild',value:'Wild',side});for(let i=0;i<4;i++)deck.push({color:'wild',value:'+4',side});if(sideCount===2)for(let i=0;i<2;i++)deck.push({color:'wild',value:'FLIP',side})}return shuffle(deck)}function shuffle(a){for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function startGame(){const names=[setup.name.trim()||'Roo Rider',...(['Macca','Shazza','Bluey'].slice(0,setup.players-1))];game={players:names.map((name,i)=>({name,emoji:EMOJIS[i],hand:[],human:i===0||setup.style==='pass',alive:true})),deck:makeDeck(),discard:[],turn:0,dir:1,side:0,pending:0,log:'Your turn — play a card or draw one.',lastWinner:null,drawn:false,roundOver:false};selected=null;awaitingPass=setup.style==='pass';for(let n=0;n<7;n++)game.players.forEach(p=>p.hand.push(game.deck.pop()));let starter=game.deck.pop();while(starter.color==='wild'||['Skip','Reverse','+2','+4','FLIP'].includes(starter.value)) {game.deck.unshift(starter);starter=game.deck.pop()}game.discard.push(starter);page='game';render();if(!game.players[0].human)nextTurn()}
function active(){return game.players[game.turn]}
function top(){return game.discard.at(-1)}
function isPlayable(c){if(!game||game.roundOver)return false;if(game.pending)return ['+2','+4'].includes(c.value)&&(setup.stack!==false);return c.color==='wild'||c.side===game.side&&(c.color===top().color||c.value===top().value)}
function cardColor(c){if(c.color==='wild')return 'linear-gradient(135deg,#d47b54 0 25%,#74a987 25% 50%,#6399c1 50% 75%,#c9ac55 75%)';return COLORS[c.color]}
function label(c){return c.value==='Reverse'?'↻':c.value==='Skip'?'⊘':c.value==='FLIP'?'⇄':c.value}
function cardMarkup(c,cls=''){let t=label(c),tag=['Skip','Reverse','FLIP','Wild','+4'].includes(c.value);return `<div class="${cls}" style="--card:${cardColor(c)};background:${cardColor(c)}" data-value="${c.value}"><span class="cnum">${t}</span><span class="${tag?'ctag':''}">${t}</span><span class="cnum bottom">${t}</span></div>`}
function gameHTML(){let p=active(),showCards=p.human&&!awaitingPass;const other=game.players.map((x,i)=>({x,i})).filter(o=>o.i!==game.turn&&o.x.alive);return `<div class="playarea"><div class="gamehead"><div><div class="eyebrow">${setup.mode==='flip'?'STORM & SCRUB':setup.mode==='mercy'?'NO WORRIES, NO MERCY':'BACKYARD MIX'} · ${game.side?'SCRUB SIDE':'STORM SIDE'}</div><h1>${game.roundOver?`<span class="winner">${game.players[game.winner].name} takes the round!</span>`:`${p.name}'s turn`}</h1></div><span class="turnpill">${game.pending?`DRAW ${game.pending} PENDING`:`${game.side?'⚡ SCRUB':'☀ STORM'} SIDE`}</span></div><section class="table"><div class="opponents">${other.map(({x,i})=>`<div class="opponent ${i===game.turn?'active':''}"><div class="avatar">${x.emoji}</div><b>${x.name}</b><small>${x.hand.length} cards</small><div class="mini-cards">${'<i class="backcard"></i>'.repeat(Math.min(x.hand.length,7))}</div></div>`).join('')}</div><div class="centerplay"><div class="deckpile" onclick="drawCard()" title="Draw a card">✳<small>DRAW PILE · ${game.deck.length}</small></div><div class="pilearea">${cardMarkup(top(),'discard-card')}<span class="turnhint">${game.pending?`PENALTY ${game.pending} — STACK OR DRAW`:game.side?'SCRUB SIDE UP':'STORM SIDE UP'}</span></div></div><div class="turnhint">${game.log}</div>${awaitingPass?`<div class="passveil"><div><div class="eyebrow">PASS THE DEVICE</div><h2>Hand it to ${p.name}</h2><p>Make sure no-one else has a squiz at your cards.</p><button class="primary" onclick="revealHand()">I'M ${p.name.toUpperCase()} — LET'S GO</button></div></div>`:''}</section><section class="handarea"><div class="handtop"><b>${p.human?'Your hand':p.name+' is thinking'} <span style="color:var(--muted);font-weight:400">${p.hand.length} cards</span></b><span>${p.hand.length===1?'LAST CARD!':''}</span></div><div class="hand">${showCards?p.hand.map((c,i)=>`<button class="card ${selected===i?'selected':''} ${isPlayable(c)?'':'disabled'}" style="--card:${cardColor(c)};background:${cardColor(c)}" onclick="selectCard(${i})" aria-label="${c.color} ${c.value}"><span class="cnum">${label(c)}</span><span class="${['Skip','Reverse','FLIP','Wild','+4'].includes(c.value)?'ctag':''}">${label(c)}</span><span class="cnum bottom">${label(c)}</span></button>`).join(''):'<div class="turnhint">Cards hidden until your turn.</div>'}</div><div class="gamecontrols">${selected!==null?`<button class="primary" onclick="playSelected()">PLAY CARD</button>`:''}<button class="secondary ${!p.human||awaitingPass?'disabled':''}" onclick="drawCard()">DRAW ${game.pending?'& TAKE '+game.pending:''}</button><button class="secondary ${!p.human||awaitingPass?'disabled':''}" onclick="callOut()">📣 LAST CARD!</button><button class="secondary" onclick="showPage('rules')">RULES</button><button class="secondary" onclick="confirmQuit()">QUIT</button></div><div class="gamefoot"><span>ROUND ${stats.played+1} · ${game.dir===1?'CLOCKWISE':'COUNTER-CLOCKWISE'}</span><div class="emojirow"><button onclick="react('🦘')">🦘</button><button onclick="react('😂')">😂</button><button onclick="react('😱')">😱</button><button onclick="react('👏')">👏</button></div><span>${p.human?'YOUR MOVE':'CPU TURN'}</span></div></section></div>`}
function bindGame(){}

function revealHand(){awaitingPass=false;render()}
function advance(){if(game.roundOver)return;let tries=0;do{game.turn=(game.turn+game.dir+game.players.length)%game.players.length;tries++}while(!game.players[game.turn].alive&&tries<game.players.length+1);selected=null;game.drawn=false;awaitingPass=setup.style==='pass'&&active().human;render();if(!active().human){clearTimeout(turnTimer);turnTimer=setTimeout(cpuTurn,750)}}
function recycle(){if(game.deck.length)return;let keep=game.discard.pop();game.deck=shuffle(game.discard);game.discard=[keep];game.log='The discard pile got a fresh shuffle.'}
function takeCards(player,count){for(let i=0;i<count;i++){recycle();if(game.deck.length)player.hand.push(game.deck.pop())}if(setup.bust!==false&&player.hand.length>=25){player.alive=false;game.log=`${player.name} busted at ${player.hand.length} cards! Out of the round.`;let survivors=game.players.filter(p=>p.alive);if(survivors.length===1){finish(survivors[0]);return true}}return false}
function drawCard(){if(!game||game.roundOver||!active().human||awaitingPass)return;if(game.pending){let n=game.pending;game.pending=0;if(!takeCards(active(),n))game.log=`${active().name} copped ${n} cards. Turn passed.`;render();setTimeout(advance,500);return}if(game.drawn){toast('You’ve already drawn this turn.');return}recycle();if(!game.deck.length)return;if(game.side===1&&setup.mode==='flip'){/* no-op: card draw stays hidden */}active().hand.push(game.deck.pop());game.drawn=true;game.log='One card drawn. Play it if it fits, or pass.';render()}
function selectCard(i){if(!active().human||awaitingPass||!isPlayable(active().hand[i])){if(active().human)toast(game.pending?'Stack a +2 or +4, or take the penalty.':'That one doesn’t match.');return}selected=i;render()}
function playSelected(){if(selected===null||!active().human)return;let c=active().hand[selected];if(!isPlayable(c))return;if(c.color==='wild'){awaitingColor={player:game.turn,index:selected};colorModal();return}applyPlay(selected,null)}
function colorModal(){let root=$('#modalRoot');root.innerHTML=`<div class="overlay"><div class="modal"><div class="eyebrow">CALL THE COLOUR</div><h2>What's the play?</h2><p>Pick the colour that everyone has to match next.</p><div class="colorpick">${Object.entries(COLORS).map(([k,v])=>`<button style="background:${v}" aria-label="${k}" onclick="chooseColor('${k}')"></button>`).join('')}</div><button class="secondary" onclick="$('#modalRoot').innerHTML='';awaitingColor=null">Nah, keep it</button></div></div>`}
function chooseColor(color){let a=awaitingColor;awaitingColor=null;$('#modalRoot').innerHTML='';applyPlay(a.index,color)}
function applyPlay(index,chosen){let p=active(),c=p.hand[index];if(game.pending&&setup.stack!==false)game.pending=0;p.hand.splice(index,1);if(chosen)c.chosen=chosen;game.discard.push(c);game.drawn=false;let name=p.name;game.log=`${name} played ${c.value}${chosen?' — '+chosen:''}.`;if(c.value==='Reverse'){game.dir*=-1;if(game.players.filter(x=>x.alive).length===2)game.turn=(game.turn+game.dir+game.players.length)%game.players.length}else if(c.value==='Skip'){game.turn=(game.turn+game.dir+game.players.length)%game.players.length}else if(c.value==='+2'||c.value==='+4')game.pending+=c.value==='+2'?2:4;else if(c.value==='FLIP'){game.side=1-game.side;game.log='The weather flipped! New side of the deck.'}if(p.hand.length===0){finish(p);return}if(p.hand.length===1){game.log+=` ${name} is down to one — call LAST CARD!`}if(game.pending===0){advance();return}if(!active().human){advance();return}selected=null;awaitingPass=setup.style==='pass'&&active().human;render()}
function callOut(){if(!active().human||awaitingPass)return;if(active().hand.length===1)toast('LAST CARD! The club heard you.');else{takeCards(active(),2);game.log='Too early! Take two cards for the false alarm.';advance()}}
function cpuTurn(){if(!game||game.roundOver||active().human)return;let p=active();if(game.pending){let idx=setup.stack===false?-1:p.hand.findIndex(c=>['+2','+4'].includes(c.value));if(idx>=0){applyPlay(idx,null);return}let n=game.pending;game.pending=0;if(takeCards(p,n)){render();return}game.log=`${p.name} took ${n} cards.`;advance();return}let choices=p.hand.map((c,i)=>({c,i})).filter(x=>isPlayable(x.c));if(choices.length){choices.sort((a,b)=>{let score=x=>(x.c.value==='+4'?5:x.c.value==='+2'?4:x.c.value==='FLIP'?3:['Skip','Reverse'].includes(x.c.value)?2:0)+(x.c.color===top().color?0:1);return score(b)-score(a)});let chosen=choices[0],color=chosen.c.color==='wild'?Object.keys(COLORS).sort((a,b)=>p.hand.filter(c=>c.color===b).length-p.hand.filter(c=>c.color===a).length)[0]:null;applyPlay(chosen.i,color);return}recycle();if(game.deck.length)p.hand.push(game.deck.pop());game.log=`${p.name} drew a card.`;advance()}
function finish(winner){game.roundOver=true;game.winner=game.players.indexOf(winner);game.log=`${winner.name} is the last one out!`;if(winner.human){stats.wins++;stats.points+=100;stats.streak++}else stats.streak=0;stats.played++;saveStats();render();if(winner.human)toast('Round won! +100 club points 🏆')}
function react(emoji){toast(`${active().name}: ${emoji}`)}
function confirmQuit(){modal('Head back to the clubhouse?','This round won’t count as a win.',`<button class="secondary" onclick="$('#modalRoot').innerHTML=''">Keep playing</button><button class="primary" onclick="$('#modalRoot').innerHTML='';showPage('home')">LEAVE ROUND</button>`)}
function modal(title,text,buttons){$('#modalRoot').innerHTML=`<div class="overlay"><div class="modal"><h2>${title}</h2><p>${text}</p><div class="modal-actions">${buttons}</div></div></div>`}
function toast(t){let el=$('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),1900)}
function tournamentHTML(){return `<div class="eyebrow">CLUB NIGHT</div><h1 class="page-title">Tournament board</h1><p class="page-sub">A proper knockout, played over three rounds. Keep the bragging rights local.</p><section class="panel" style="max-width:760px"><div class="eyebrow">WEEKEND BACKYARD CUP</div><h2 style="font-size:23px;margin:9px 0">The Gumtree Gauntlet</h2><p style="color:var(--muted);font-size:12px;line-height:1.6">Three quick rounds. Every win earns points toward your local club standing. Tournament mode is coming soon; jump into a match while the snags are on.</p><div class="statsrow"><div class="statbox"><small>YOUR WINS</small><strong>${stats.wins}</strong></div><div class="statbox"><small>YOUR POINTS</small><strong>${stats.points}</strong></div><div class="statbox"><small>STREAK</small><strong>${stats.streak}</strong></div></div><button class="primary" style="margin-top:18px" onclick="showPage('setup')">PLAY A QUALIFIER →</button></section>`}
function leaderHTML(){let rows=[{name:setup.name,emoji:'🦘',points:stats.points,wins:stats.wins},{name:'Shazza',emoji:'🦜',points:420,wins:7},{name:'Macca',emoji:'🐨',points:360,wins:6},{name:'Bluey',emoji:'🦉',points:280,wins:4}].sort((a,b)=>b.points-a.points);return `<div class="eyebrow">LOCAL LEGENDS</div><h1 class="page-title">Leaderboard</h1><p class="page-sub">Your device, your club. Stats are saved locally in this browser.</p><section class="panel" style="max-width:740px;padding:8px 18px"><div class="rankrow" style="color:var(--muted);font:9px 'DM Mono'"><span>RANK</span><span>PLAYER</span><span style="text-align:right">CLUB PTS</span></div>${rows.map((r,i)=>`<div class="rankrow"><span class="rank">${String(i+1).padStart(2,'0')}</span><span class="rankname"><i>${r.emoji}</i><span>${r.name}${i===0&&r.points===stats.points?' · YOU':''}<small style="display:block;color:var(--muted);font-size:9px;margin-top:3px">${r.wins} round wins</small></span></span><span class="points">${r.points} PTS</span></div>`).join('')}</section><p style="font-size:10px;color:var(--muted);margin-top:13px">Online play and a shared global ladder aren't connected in this demo.</p>`}
function rulesHTML(){return `<div class="eyebrow">QUICK FIELD GUIDE</div><h1 class="page-title">How to play</h1><p class="page-sub">A fresh deck of backyard chaos. Get rid of every card to win.</p><div class="rulegrid"><article class="rule"><b>① Match or make a move</b><p>Play a card matching the colour or symbol on top. Wild cards can be played any time. If nothing fits, draw one.</p></article><article class="rule"><b>② Stack the pressure</b><p>When a +2 or +4 lands, stack another draw card to pass the total along (if stacking is on). Otherwise, take the whole lot.</p></article><article class="rule"><b>③ Flip the weather</b><p>Storm & Scrub cards change the active side. The Scrub side is rougher; colours and numbers still match on their own side.</p></article><article class="rule"><b>④ Last card!</b><p>Hit the shout button when you're down to one card. Empty your hand to win. A false alarm costs two cards.</p></article><article class="rule"><b>⑤ Don't bust</b><p>In No Mercy, 25 cards is too many. Hit that limit and you're out; last player standing wins.</p></article><article class="rule"><b>Local game modes</b><p>Play against local AI or pass the device around. Online multiplayer and cross-device leaderboards are not connected in this build.</p></article></div><button class="primary" style="margin-top:20px" onclick="showPage('setup')">GOT IT — DEAL IN →</button>`}
let audioCtx=null,osc=null;$('#soundToggle').addEventListener('click',()=>{setup.music=!setup.music;let b=$('#soundToggle');b.style.color=setup.music?'var(--lime)':'';if(setup.music)startMusic();else stopMusic();toast(setup.music?'Backyard ambience on ♫':'Music off')});function startMusic(){try{audioCtx=audioCtx||new(window.AudioContext||window.webkitAudioContext)();if(osc)return;osc=audioCtx.createOscillator();let gain=audioCtx.createGain();osc.type='sine';osc.frequency.value=110;gain.gain.value=.012;osc.connect(gain);gain.connect(audioCtx.destination);osc.start()}catch(e){}}function stopMusic(){if(osc){osc.stop();osc=null}}
render();

