const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
  const browser=await chromium.launch({headless:true,args:['--no-sandbox']});
  const page=await browser.newPage({viewport:{width:1365,height:900}});
  const errors=[];page.on('pageerror',e=>errors.push(e.message));
  await page.goto('http://localhost:3002');
  await page.getByRole('button',{name:/PLAY A ROUND/i}).click();
  await page.evaluate(()=>startGame());
  await page.waitForTimeout(100);
  const state=await page.evaluate(()=>({turn:game.turn,hand:game.players[0].hand.length,plays:document.querySelectorAll('.card').length,legal:[...document.querySelectorAll('.card:not(.disabled)')].length}));
  const legal=page.locator('.card:not(.disabled)');
  if(await legal.count()){
    await legal.first().click();
    const play=page.getByRole('button',{name:'PLAY CARD'});
    if(await play.count()) await play.click();
    if(await page.locator('.overlay').count()) await page.locator('.colorpick button').first().click();
  } else {
    await page.getByRole('button',{name:/DRAW/i}).first().click();
    await page.waitForTimeout(100);
    if(await page.getByRole('button',{name:'END TURN'}).count()) await page.getByRole('button',{name:'END TURN'}).click();
  }
  await page.waitForTimeout(1000);
  const afterAI=await page.evaluate(()=>({turn:game.turn,roundOver:game.roundOver,log:game.log}));
  await page.evaluate(()=>{showPage('setup');setup.style='pass';setup.players=2;startGame()});
  const passVisible=await page.locator('.passveil').count();
  await page.getByRole('button',{name:/LET'S GO/i}).click();
  const passReveal=await page.locator('.card').count();
  await page.evaluate(()=>{setup.music=true;startMusic();stopMusic()});
  await page.screenshot({path:'/tmp/opencode/last-one-out.jpg',type:'jpeg',quality:80,fullPage:true});
  console.log(JSON.stringify({initial:state,afterAI,passVisible,passReveal,errors},null,2));
  await browser.close();
})();

