 await page.goto('http://localhost:3002');
 await page.evaluate(()=>{setup.mode='mix';setup.style='ai';setup.players=2;startGame();game.side=0;game.discard=[{color:'wild',value:'Wild',side:0,chosen:'gum'}];game.players[0].hand=[{color:'gum',value:'4',side:0},{color:'sun',value:'4',side:0},{color:'gum',value:'5',side:0}]});
