 else {await page.getByRole('button',{name:/DRAW/i}).first().click();await page.waitForTimeout(600);}
 await page.waitForTimeout(100);
 const passResult=await page.evaluate(()=>({turn:game.turn,pass:awaitingPass,roundOver:game.roundOver}));
 await page.getByRole('button',{name:'Music'}).click();
