 function applyPlay(index,chosen){let p=active(),c=p.hand[index];if(game.pending&&setup.stack!==false)game.pending=0;p.hand.splice(index,1);if(chosen)c.chosen=chosen;game.discard.push(c);game.drawn=false;let name=p.name;game.log=`${name} played ${c.value}${chosen?' — '+chosen:''}.`;if(c.value==='Reverse'){game.dir*=-1}else if(c.value==='Skip'){game.turn=(game.turn+game.dir+game.players.length)%game.players.length}else if(c.value==='+2'||c.value==='+4')game.pending+=c.value==='+2'?2:4;else if(c.value==='FLIP'){game.side=1-game.side;game.log='The weather flipped! New side of the deck.'}if(p.hand.length===0){finish(p);return}if(p.hand.length===1){game.log+=` ${name} is down to one — call LAST CARD!`}if(game.pending===0){advance();return}if(!active().human){advance();return}selected=null;awaitingPass=setup.style==='pass'&&active().human;render()}
